create extension if not exists pgcrypto;
create type day_type as enum ('maintenance','execution','sales','life','review');
create type task_status as enum ('todo','done','archived','decision_required');
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null default 'Founder',timezone text not null default 'Europe/London',income_target numeric not null default 4500,created_at timestamptz not null default now());
create table if not exists goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,title text not null,category text not null,target numeric,period_start date,period_end date,status text not null default 'active');
create table if not exists tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,title text not null,category text not null default 'TDO',status task_status not null default 'todo',due_at timestamptz,estimated_minutes int not null default 30,importance int not null default 3,urgency int not null default 3,revenue_impact int not null default 0,strategic_impact int not null default 0,energy text not null default 'medium',recurring_rule text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists daily_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,plan_date date not null,day_type day_type not null,mission text not null,capacity_minutes int not null,created_at timestamptz not null default now(),unique(user_id,plan_date));
create table if not exists daily_plan_tasks(plan_id uuid not null references daily_plans(id) on delete cascade,task_id uuid not null references tasks(id) on delete cascade,rank int not null,bucket text not null check(bucket in ('must','should','optional')),primary key(plan_id,task_id));
create table if not exists leads(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,name text not null,company text,website text,status text not null default 'New',estimated_value numeric not null default 0,last_contact date,next_follow_up date,probability numeric not null default 0,notes text);
create table if not exists transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,kind text not null check(kind in ('income','expense')),source text not null,amount numeric not null,category text,occurred_on date not null,notes text);
create table if not exists habits(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,name text not null,frequency text not null,target numeric not null default 1,active boolean not null default true);
create table if not exists habit_entries(id uuid primary key default gen_random_uuid(),habit_id uuid not null references habits(id) on delete cascade,entry_date date not null,completed numeric not null default 0,unique(habit_id,entry_date));
create table if not exists learning_modules(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,topic text not null,stage text not null,current_module text,next_lesson text,hours_studied numeric not null default 0,target_hours numeric not null default 0,confidence int not null default 0);
create table if not exists events(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,title text not null,starts_at timestamptz not null,ends_at timestamptz,category text not null default 'TDO',notes text);
create table if not exists reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,period_type text not null,period_start date not null,period_end date not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table profiles enable row level security; alter table goals enable row level security; alter table tasks enable row level security; alter table daily_plans enable row level security; alter table daily_plan_tasks enable row level security; alter table leads enable row level security; alter table transactions enable row level security; alter table habits enable row level security; alter table habit_entries enable row level security; alter table learning_modules enable row level security; alter table events enable row level security; alter table reviews enable row level security;
create policy profiles_self on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy goals_self on goals for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy tasks_self on tasks for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy plans_self on daily_plans for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy plan_tasks_self on daily_plan_tasks for all using(exists(select 1 from daily_plans p where p.id=plan_id and p.user_id=auth.uid())) with check(exists(select 1 from daily_plans p where p.id=plan_id and p.user_id=auth.uid()));
create policy leads_self on leads for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy transactions_self on transactions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy habits_self on habits for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy habit_entries_self on habit_entries for all using(exists(select 1 from habits h where h.id=habit_id and h.user_id=auth.uid())) with check(exists(select 1 from habits h where h.id=habit_id and h.user_id=auth.uid()));
create policy learning_self on learning_modules for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy events_self on events for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy reviews_self on reviews for all using(user_id=auth.uid()) with check(user_id=auth.uid());